questionvariables.text:
/* Define the functions */ 
const1:rand(3)+1;
const2:const1+2;
f1(x) := x^2 + const1; 
f2(x) := x + const2;  
/* Find the intersection points */ 
intersection_points: solve(f1(x) = f2(x), x); 
b: rhs(intersection_points[1]); 
a: rhs(intersection_points[2]);  
x1:f1(a);
y1:f1(b);
/* Define the integral for volume calculation */ 
integral_expr: int((f2(x))^2 - (f1(x))^2, x, a, b);  
/* Calculate the volume */ 
volume: %pi*(integral_expr); 


/*worked soln*/
eqn1:expand((f2(x))^2);
eqn2: expand((f1(x))^2);
eqn3:eqn1-eqn2;
eqn4:int(eqn3,x);
eqn5:at(eqn4,[x=b]);
eqn6:at(eqn4,[x=a]);
eqn7:eqn5-eqn6;


/*board coord */
minx:-1*(const1+1);
miny:minx;
maxy:(-1*minx)+7;
maxx:-1*minx
